// ===== Context 的问题：全量重渲染 =====
const CountContext = React.createContext();

function CountProvider({ children }) {
  const [count, setCount] = React.useState(0);
  // value 是新对象引用，每次 count 变化都触发所有消费者重渲染
  return (
    <CountContext.Provider value={{ count, setCount }}>
      {children}
    </CountContext.Provider>
  );
}

// 这个组件只用了 count，但 setCount 变了它也会重渲染
function Display() {
  const { count } = React.useContext(CountContext);
  return <span>{count}</span>;
}

// 这个组件只用了 setCount（不会变），但 count 变了它也会重渲染
function Button() {
  const { setCount } = React.useContext(CountContext);
  return <button onClick={() => setCount(c => c + 1)}>+1</button>;
}

// ===== Zustand 的方案：选择器精确订阅 =====
import { create } from 'zustand';

const useStore = create(set => ({
  count: 0,
  increment: () => set(state => ({ count: state.count + 1 }))
}));

// 只订阅 count，count 不变则不重渲染
function DisplayZustand() {
  const count = useStore(state => state.count);
  return <span>{count}</span>;
}

// 只订阅 increment 函数引用（稳定），count 变化不会重渲染此组件
function ButtonZustand() {
  const increment = useStore(state => state.increment);
  return <button onClick={increment}>+1</button>;
}

// ===== React Query：服务端状态管理 =====
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

function TodoList() {
  const queryClient = useQueryClient();
  const { data, isLoading, error } = useQuery({
    queryKey: ['todos'],
    queryFn: () => fetch('/api/todos').then(r => r.json()),
    staleTime: 5 * 60 * 1000, // 5 分钟内不重新请求
  });

  const mutation = useMutation({
    mutationFn: newTodo =>
      fetch('/api/todos', { method: 'POST', body: JSON.stringify(newTodo) }),
    onSuccess: () => {
      // 自动重取 todos，保持缓存一致性
      queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });

  if (isLoading) return <p>Loading...</p>;
  if (error) return <p>Error: {error.message}</p>;
  return (
    <ul>
      {data.map(todo => <li key={todo.id}>{todo.title}</li>)}
      <button onClick={() => mutation.mutate({ title: 'New' })}>Add</button>
    </ul>
  );
}
